create extension if not exists pg_net with schema extensions; create schema if not exists editorial_private; revoke all on schema editorial_private from public, anon, authenticated; create table if not exists editorial_private.asset_imports (asset_key text primary key, payload text not null, status text not null default 'pending', error text, created_at timestamptz not null default now()); alter table editorial_private.asset_imports enable row level security; create table if not exists editorial_private.worker_capabilities (name text primary key, token_hash text not null, expires_at timestamptz not null); alter table editorial_private.worker_capabilities enable row level security; create or replace function public.editorial_pending_assets() returns jsonb language sql security definer set search_path = '' as $$ select coalesce(jsonb_agg(to_jsonb(a)), '[]'::jsonb) from (select asset_key,payload from editorial_private.asset_imports where status='pending' order by asset_key limit 12) a $$; revoke all on function public.editorial_pending_assets() from public,anon,authenticated; grant execute on function public.editorial_pending_assets() to service_role; create or replace function public.editorial_asset_result(p_key text,p_error text default null) returns void language sql security definer set search_path = '' as $$ update editorial_private.asset_imports set status=case when p_error is null then 'completed' else 'failed' end,error=p_error,payload=case when p_error is null then '' else payload end where asset_key=p_key $$; revoke all on function public.editorial_asset_result(text,text) from public,anon,authenticated; grant execute on function public.editorial_asset_result(text,text) to service_role; create or replace function public.editorial_worker_authorized(p_name text,p_token text) returns boolean language sql security definer set search_path = '' as $$ select exists(select 1 from editorial_private.worker_capabilities where name=p_name and expires_at>now() and token_hash=encode(extensions.digest(p_token,'sha256'),'hex')) $$; revoke all on function public.editorial_worker_authorized(text,text) from public,anon,authenticated; grant execute on function public.editorial_worker_authorized(text,text) to service_role;

